    manager.reconcileBusy = false;

    // 禁用：先启动再禁用 → stop 并移除，报变更。
    store.upsert(normalizeServer(quietServer("g-off")));
    manager.reconcileServers();
    assert.ok(manager.supervisors.has("g-off"));
